urlset:
{% for post in posts %}

  {{ post.permalink | uriencode }}
  {% if post.updated %}
  {{ post.updated | formatDate }}
  {% elif post.date %}
  {{ post.date | formatDate }}
  {% endif %}
  monthly
  0.6

{% endfor %}

{# 홈·카테고리 lastmod는 배포 시각(sNow)이 아니라 소속 글 중 가장 최근 날짜로 고정 #}

  {{ config.url | uriencode }}
  {% if posts.length %}{{ posts[0].updated | formatDate }}{% endif %}
  daily
  1.0


{% for tag in tags %}

  {{ tag.permalink | uriencode }}
  {% set latest = tag.posts.sort('-date').first() %}
  {% if latest %}{{ latest.date | formatDate }}{% endif %}
  weekly
  0.2

{% endfor %}

{% for cat in categories %}

  {{ cat.permalink | uriencode }}
  {% set latest = cat.posts.sort('-date').first() %}
  {% if latest %}{{ latest.date | formatDate }}{% endif %}
  weekly
  0.2

{% endfor %}
